-- app/assets/seed.db schema (schema_version = 6)
-- Generated by app/tools/seedbuild/build_seed.py. Do not hand-edit the built DB.
-- Percentiles are computed at build time over the analysis universe
-- (is_licensed = 0, est_year in 2007..2025). Licensed books carry NULL percentiles.
-- v2 added the additive deep_ranks table (D2); v3 adds form/lqs/vel_pctl to books
-- (V3 quality anchors; time channels retired 2026-11-19. See app/docs/09 appendix E.8 and docs/length-weighted-quality.md).
-- v4 adds calendar_universe: estimated whole-platform releases per day for the
-- 发书日历 dual-count view (app/docs/14 P1).
-- v5 adds contest_awards: per-edition award winners (net 911 rows, 11 editions)
-- for the archive-page award block and the detail-page badge
-- (docs/contest-display-in-app.md §6; source analysis/out/contest_awards_normalized.csv).
-- v6 adds runtime quality metrics (app/docs/18-runtime-metrics.md, report 24):
-- books.cqs/cps/len_norm/cqs_state are precomputed over the calibration
-- universe; the calib_* tables let the engine band and score discovered books
-- at runtime (phase 2). Cumulative clicks never enters the formulas (docs/12).
-- v7 adds eras_anchors: the 281 nid-axis dating anchors (eras.load_anchors,
-- report 01) so the engine can estimate est_year for discovered books at
-- runtime (app/docs/18-runtime-metrics.md P2).
-- Uniqueness: cover_url is unique per book on the platform (NULL for missing
-- covers); title is unique on the platform but snapshots can carry rename-window
-- artifacts, so title duplicates are checked in validate.py, not constrained here.

PRAGMA page_size = 4096;

CREATE TABLE books(
  nid         INTEGER PRIMARY KEY,
  title       TEXT    NOT NULL,
  author      TEXT    NOT NULL,
  genre       TEXT,
  price_type  TEXT,
  status      TEXT,
  contest     TEXT,
  words       INTEGER,
  clicks      INTEGER,
  favs        INTEGER,
  praises     INTEGER,
  featured    INTEGER,
  cover_url   TEXT,
  updated_at  TEXT,
  est_year    INTEGER NOT NULL,
  est_date    TEXT    NOT NULL,
  est_conf    TEXT    NOT NULL,
  tags        TEXT,
  fav_pctl    REAL,
  click_pctl  REAL,
  praise_pctl REAL,
  pr          REAL,
  pctl_pr     REAL,
  form        TEXT    NOT NULL,
  lqs         REAL,
  lqs_pctl    REAL,
  vel_pctl    REAL,
  cqs         REAL,
  cqs_state   TEXT,
  cps         REAL,
  len_norm    REAL,
  is_licensed INTEGER NOT NULL DEFAULT 0,
  UNIQUE(cover_url)
);

CREATE TABLE book_tags(
  nid INTEGER NOT NULL,
  tag TEXT    NOT NULL,
  PRIMARY KEY(nid, tag)
);

-- D2 full-universe generation Top-200 boards (see analysis/reports/21_deep_ranks.md).
-- Read-only, additive: never joined into books, never feeds a percentile denominator.
-- Depth is min(200, eligible books); pr additionally requires favs >= 10.
CREATE TABLE deep_ranks(
  est_year  INTEGER NOT NULL,
  metric    TEXT    NOT NULL,
  rank_no   INTEGER NOT NULL,
  nid       INTEGER NOT NULL,
  title     TEXT    NOT NULL,
  author    TEXT    NOT NULL,
  genre     TEXT,
  value     REAL,
  pctl      REAL,
  cover_url TEXT,
  PRIMARY KEY(est_year, metric, rank_no),
  UNIQUE(est_year, metric, nid)
);

CREATE INDEX idx_deep_lookup ON deep_ranks(metric, est_year, rank_no);

-- v4: estimated whole-platform releases per day (发书日历, app/docs/14 P1).
-- Source = full dataset INCLUDING licensed, dated by eras.estimate (281
-- nid-axis anchors; median interpolation error 2 days). The bundled seed is a
-- clickable subset of this table; only days with >= 1 book are stored, the
-- engine fills zero days. Display range 2007..2025 (founding year 2007,
-- content right-censored at content_end).
CREATE TABLE calendar_universe(
  day            TEXT    PRIMARY KEY,
  universe_count INTEGER NOT NULL
);

-- v5: contest award winners. Additive display facts only: these rows never
-- join into percentile denominators, never feed admission, and award never
-- orders or scores anything (docs/contest-display-in-app.md §6, red line).
-- award is the reliable tier name for the 44 books whose activity page kept
-- Chinese names, and the placeholder 待逐档标定 for the other 867 (the display
-- layer maps the placeholder to 征文获奖; the raw placeholder never shows).
-- 140 of the 911 rows have no books row (out-of-library); they stay in the
-- table and become visible if/when their books are fetched later.
CREATE TABLE contest_awards(
  nid        INTEGER NOT NULL,
  edition    TEXT    NOT NULL,   -- '十二征'/'七征冬征'/'2025春征'/...
  award      TEXT    NOT NULL,   -- '金奖'/'银奖'/... or '待逐档标定'
  category   TEXT,               -- 长篇/中篇/短篇/对话 when the page exposed it
  source_nid TEXT    NOT NULL,   -- source activity page, e.g. zw20240504
  PRIMARY KEY(nid, edition)
);
CREATE INDEX idx_awards_edition ON contest_awards(edition, nid);

-- Key/value keeps the metadata table from needing a migration per new field.
CREATE TABLE seed_meta(
  key   TEXT PRIMARY KEY,
  value TEXT NOT NULL
);

-- v6 runtime-metric calibration tables (app/docs/18-runtime-metrics.md).
-- Bounds/anchors/medians are fitted over the calibration universe at build
-- time (report 24; kappa=500). They exist so the engine can band and score
-- discovered books at runtime (phase 2) without the analysis stack.
CREATE TABLE calib_fav_bounds(
  form     TEXT    NOT NULL,
  est_year INTEGER NOT NULL,
  p50      REAL    NOT NULL,
  p75      REAL    NOT NULL,
  p90      REAL    NOT NULL,
  PRIMARY KEY(form, est_year)
);

CREATE TABLE calib_len_anchors(
  form TEXT PRIMARY KEY,
  lo   REAL    NOT NULL,
  hi   REAL    NOT NULL
);

CREATE TABLE calib_cqs_median(
  form     TEXT    NOT NULL,
  est_year INTEGER NOT NULL,
  genre    TEXT    NOT NULL,
  fband    TEXT    NOT NULL,
  med      REAL    NOT NULL,
  cell_n   INTEGER NOT NULL,
  PRIMARY KEY(form, est_year, genre, fband)
);

CREATE TABLE calib_cps_median(
  form     TEXT    NOT NULL,
  est_year INTEGER NOT NULL,
  band     TEXT    NOT NULL,
  genre    TEXT    NOT NULL,
  med      REAL    NOT NULL,
  PRIMARY KEY(form, est_year, band, genre)
);

-- v7: the nid-axis dating anchors (analysis/anchors/nid_anchors.jsonl via
-- eras.load_anchors; interpolation error median 2 days). day = epoch days.
-- The engine interpolates log(nid) ↔ day piecewise-linearly to date
-- discovered books at runtime (app/docs/18-runtime-metrics.md P2).
CREATE TABLE eras_anchors(
  nid INTEGER PRIMARY KEY,
  day INTEGER NOT NULL
);

-- Eleven indexes; predicates match the engine queries.
CREATE INDEX idx_bt              ON book_tags(tag, nid);
CREATE INDEX idx_updated         ON books(updated_at);
CREATE INDEX idx_author          ON books(author);
CREATE INDEX idx_year_favpctl    ON books(est_year, fav_pctl DESC);
CREATE INDEX idx_year_clickpctl  ON books(est_year, click_pctl DESC);
CREATE INDEX idx_genre_favs      ON books(genre, favs DESC);
CREATE INDEX idx_favs            ON books(favs DESC);
CREATE INDEX idx_pr              ON books(pr DESC);
CREATE INDEX idx_form_cqs        ON books(form, cqs DESC);
CREATE INDEX idx_shortfav        ON books(favs DESC)
  WHERE words <= 50000 AND status = '已完结' AND is_licensed = 0;
